const targetById = new Map<string, PlayableTarget>(
  PLAYABLE_TARGETS.map((target) => [target.categorySetId, target]),
);
const targetFor = (categorySetId: string): PlayableTarget => {
  const target = targetById.get(categorySetId);
  if (target === undefined) throw new Error(`Unknown playable target: ${categorySetId}`);
  return target;
};
const slug = (value: string): string => value.normalize('NFKD').replace(/[\u0300-\u036f]/gu, '')
  .toLocaleLowerCase('en').replace(/%[0-9a-f]{2}/giu, '-').replace(/[^a-z0-9]+/gu, '-').replace(/^-|-$/gu, '');
const hash = (value: string): string => {
  let result = 0x811c9dc5;
  for (const character of value) result = Math.imul(result ^ (character.codePointAt(0) ?? 0), 0x01000193);
  return (result >>> 0).toString(36);
};
const question = (categorySetId: string, seed: QuestionSeed, index: number): PlayableQuestion => {
  const [page, clueEn, clueEt, responseEn, responseEt, explanationEn, explanationEt, variantsEn = [], variantsEt = []] = seed;
  const tier = (index + 1) as 1 | 2 | 3 | 4 | 5;
  const subjectKey = `history:${slug(page)}`;
  return {
    key: `playable:${categorySetId}:${tier}`,
    factKey: `fact:${subjectKey}:${hash(`${clueEn}\0${responseEn}`)}`,
    tier,
    subjectKey,
    clue: { en: clueEn, et: clueEt },
    response: { en: responseEn, et: responseEt },
    acceptedVariants: { en: variantsEn, et: variantsEt },
    explanation: { en: explanationEn, et: explanationEt },
    source: {
      sourceId: `source:${subjectKey}`,
      title: `${decodeURIComponent(page).replace(/_/gu, ' ')} — Wikipedia`,
      url: `https://en.wikipedia.org/wiki/${page}`,
      license: 'CC-BY-SA-4.0',
      retrievedAt: RETRIEVED_AT,
    },
  };
};

export const HISTORY_CATEGORIES: readonly PlayableCategory[] = HISTORY_SEEDS.map(
  ([categorySetId, nameEn, nameEt, questions]) => ({
    ...targetFor(categorySetId),
    name: { en: nameEn, et: nameEt },
    questions: questions.map((seed, index) => question(categorySetId, seed, index)),
  }),
);
